INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_94c7df19c34b2a7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_days', 'World Biofuel Day is observed on which date?', '{"A":"August 20","B":"August 15","C":"August 10","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation World Biofuel Day is observed every year on August 10th to raise awareness about the importance of non-fossil fuels as a cleaner alternative to traditional fossil fuels. It honors Sir Rudolf Diesel’s historic 1893 experiment running a mechanical engine on peanut oil. ***', 0, 0, 0, 1790970547896) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_2fb8c42d9db0999d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_days', 'When is World Humanitarian Day observed?', '{"A":"17 August","B":"19 August","C":"18 August","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Observed annually on August 19, World Humanitarian Day honors aid workers who risk their lives to deliver life-saving support and remembers those who died in the line of duty.It was established by the United Nations to mark the 2003 bombing of the UN headquarters in Baghdad, Iraq.***', 0, 0, 0, 1790970547896) ON CONFLICT(id) DO NOTHING;
