INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_2031730f7fcb93d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_sports', 'Which Tennis player has won the Paris Masters title?', '{"A":"Roger Federer","B":"Daniil Medvedev","C":"Rafael Nadal","D":"Novak Djokovic"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Russian tennis player Daniil Medvedev has clinched his maiden Paris Masters title. This is also his career’s eighth title. He has registered his victory against the German star Alexander Zverev. It was the first time that the two players were in the finals of any international tournament.', 0, 0, 0, 1790970548610) ON CONFLICT(id) DO NOTHING;
