INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_0f47d83ba71a89de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Pulitzer prize is awarded for outstanding work in the field of _____?', '{"A":"Scuba","B":"Science & Tech","C":"Journalism","D":"Film Industry"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pulitzer Prize is awarded for outstanding work in journalism and several other fields.It was established by Joseph Pulitzer.He was a Hungarian-American newspaper publisher.The first Pulitzer Prizes were awarded in 1917.Major categories include Journalism, Letters, Drama, and Music.The Pulitzer Prizes are administered by Columbia University in New York City.Last verified 08-08-2026', 0, 0, 0, 1790970548627) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_d6a588005abc0595', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Which of the following scientists got Nobel Prize 2025 in Chemistry?', '{"A":"Moungi G. Bawendi, Louis E. Brus, and Alexei I. Ekimov","B":"Susumu Kitagawa, Richard Robson, and Omar M. Yaghi","C":"David Baker, Dennis Hassabis, and John M. Jumper","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scientists awarded: Susumu Kitagawa, Richard Robson, and Omar M. Yaghi Field of study: Metal-organic frameworks (MOFs) Reason for the award: Their work on developing MOFs, which have significant potential in areas like clean energy storage, carbon capture, and advanced material science.About Chemistry Nobel Prize 2024Co-winners: David Baker, John Jumper, Briton DemisThey are scientists from the United States of America (USA) ***', 0, 0, 0, 1790970548627) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_48276d1da5cbf4f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many times Nobel Peace Prize has been awarded to organizations between 1901 and 2023?', '{"A":"27","B":"28","C":"29","D":"30"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nobel Peace Prize has been awarded 30 times to organisations between 1901 and 2023.27 individual organisations have been awarded the Nobel Peace Prize, as UNHCR, the Office of the United Nations High Commissioner for Refugees, has received the Nobel Peace Prize twice, in 1954 and 1981, and the work of Comité international de la Croix Rouge (International Committee of the Red Cross) (ICRC) has been honoured three times, in 1917, 1944 and 1963.', 0, 0, 0, 1790970548627) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_e468597c04409ae6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many women have been awarded Nobel Peace Prize from 1901 until 2023?', '{"A":"17","B":"18","C":"19","D":"20"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Of the 111 individuals awarded the Nobel Peace Prize, 19 are women. The first time a Nobel Peace Prize was awarded to a woman was in 1905, to Bertha von Suttner.', 0, 0, 0, 1790970548627) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_92de8a3b5cf14756', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many women have been awarded Nobel Prize in Literature from 1901 to 2023?', '{"A":"13","B":"15","C":"17","D":"18"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 17 women have been awarded the Nobel Prize in Literature. Swedish author Selma Lagerlöf was the first woman to be awarded in 1909. Selma Lagerlöf was awarded five years before she was elected to the Swedish Academy, the Nobel Prize awarding institution responsible for selecting Nobel Prize laureates in literature.', 0, 0, 0, 1790970548627) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_d00c653a08a8382e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many women have been awarded the Nobel Prize in Chemistry from 1901 to 2023?', '{"A":"5","B":"6","C":"7","D":"8"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1911 – Marie Curie (also awarded the 1903 Nobel Prize in Physics)1935 – Irène Joliot-Curie (daughter of Marie Curie and wife of Frédéric Joliot)1964 – Dorothy Crowfoot Hodgkin2009 – Ada Yonath2018 – Frances H. Arnold2020 – Emmanuelle Charpentier2020 – Jennifer A. Doudna2022 – Carolyn R. Bertozzi', 0, 0, 0, 1790970548627) ON CONFLICT(id) DO NOTHING;
