INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_f0ef5a70fd029a0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many women have been awarded the Nobel Prize in Physics from 1901 to 2023?', '{"A":"3","B":"4","C":"5","D":"6"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 5 women have been awarded the Nobel Prize in Physics Marie Curie in 1903 Maria Goeppert-Mayer in 1963 Donna Strickland in 2018 Andrea Ghez in 2020 Anne L’Huillier in 2023.', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_8f37ed58bbecd90a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'What will be the monetary award for 2023 Nobel Prizes?', '{"A":"10 million SEK","B":"11 million SEK","C":"12 million SEK","D":"13 million SEK"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nobel Foundation added the 84, 000 euros to each category''s prize pot, meaning that the 2023 laureates will receive 924,000 euros (11 million Swedish krona).In 2021 and 2022 monetary award was 10 million SEK', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_36a7b15cb6d14091', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Nobel Prize laureate ''Claudia Goldin'' belongs to which country?', '{"A":"USA","B":"Russia","C":"Germany","D":"Norway"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Claudia Goldin is an American economic historian and labor economist. In 1990, Goldin became the first tenured woman at Harvard''s economics department. In 2023, she was awarded the Nobel Memorial Prize in Economic Sciences "for having advanced our understanding of women''s labor market outcomes".', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_e5794223ae1f6795', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Which of the following is the only posthumous Nobel Peace Prize laureate?', '{"A":"Dag Hammarskjöld","B":"Erik Axel Karlfeldt","C":"Winston Churchill","D":"Linus Pauling"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There is one posthumous Nobel Peace Prize, to Dag Hammarskjöld in 1961.', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_1be515e7369dd281', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many Nobel Peace Prize laureates under arrest at the time of the award?', '{"A":"3","B":"4","C":"5","D":"6"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation German pacifist and journalist Carl von OssietzkyBurmese politician Aung San Suu KyiChinese human rights activist Liu XiaoboBelarus human rights advocate Ales BialiatskiIranian human rights advocate and freedom fighter Narges Mohammadi', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_efbf466e86620d94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Narges Mohammadi is a Nobel Prize laureate belongs to which country?', '{"A":"Egypt","B":"Afghanistan","C":"Morocco","D":"Iran"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Narges Mohammadi is a woman, a human rights advocate, and a freedom fighter. Her brave struggle for freedom of expression and the right of independence has come with tremendous personal costs. Altogether, the regime in Iran has arrested her 13 times, convicted her five times, and sentenced her to a total of 31 years in prison and 154 lashes.Narges Mohammadi is still in prison.', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_02606714198ed8fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many people have been awarded the Nobel Prize in Literature more than once?', '{"A":"2","B":"3","C":"4","D":"No one"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation No one has been awarded the Nobel Prize in Literature more than once.', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_7518d4c630890245', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'How many people have declined the Nobel Prize in Literature?', '{"A":"2","B":"3","C":"4","D":"No one"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Two people have declined the Nobel Prize in LiteratureBoris Pasternak, the 1958 Nobel Prize in Literature, “Accepted first, later caused by the authorities of his country (Soviet Union) to decline the Prize”.Jean Paul Sartre, the 1964 Nobel Prize in Literature, declined the prize because he had consistently declined all official honors.', 0, 0, 0, 1790970548636) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_c474abd9f120c886', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Louis E. Brus Nobel Prize laureate belongs to which country?', '{"A":"USA","B":"UK","C":"Germany","D":"France"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Louis E. Brus is the S. L. Mitchell Professor of Chemistry at Columbia University and one of the three winners of the Nobel prize in Chemistry (2023).', 0, 0, 0, 1790970548645) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_6ac7ee66e37e4447', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'To date, the youngest Nobel Prize laureate in physics is?', '{"A":"Lawrence Bragg","B":"Pierre Agostini","C":"Andrea Ghez","D":"Anne L''Huillier"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To date, the youngest Nobel Prize laureate in physics is Lawrence Bragg, who was 25 years old when he was awarded the Nobel Prize together with his father in 1915.', 0, 0, 0, 1790970548645) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_6b8bc027de96eb33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Anne L''Huillier Nobel Prize laureate belongs to which country?', '{"A":"Germany","B":"USA","C":"Hungary","D":"France"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anne L''Huillier is a French physicist, and professor of atomic physics at Lund University in Sweden.In 2003 she and her group beat the world record with the smallest laser pulse of 170 attoseconds.In 2023, jointly with Pierre Agostini and Ferenc Krausz, she was awarded the Nobel Prize in Physics', 0, 0, 0, 1790970548645) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_6e92b11ff871d7b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Ferenc Krausz Nobel Prize laureate belongs to which country?', '{"A":"France","B":"Hungary","C":"USA","D":"Germany"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ferenc Krausz is a Hungarian-Austrian physicist working in attosecond science.In 2023, jointly with Pierre Agostini and Anne L''Huillier, he was awarded the Nobel Prize in Physics.', 0, 0, 0, 1790970548645) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_a0dad5b9a974711f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_awards', 'Pierre Agostini Nobel Prize laureate belongs to which country?', '{"A":"France","B":"Hungary","C":"USA","D":"Germany"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pierre Agostini is a French experimental physicist known for his pioneering work in attosecond science.He was awarded the 2023 Nobel Prize in Physics alongside Ferenc Krausz and Anne L''Huillier.', 0, 0, 0, 1790970548645) ON CONFLICT(id) DO NOTHING;
