INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_5c9bbb338a152a2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_defense', 'The war between Ukraine and Russia started on which date?', '{"A":"29 February 2022","B":"21 February 2022","C":"28 February 2022","D":"24 February 2022"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Russo-Ukrainian war began in February 2014 and is ongoingDate: Late February 2014 – present (12 years, 2 months, 1 week and 4 days)Location: Ukraine, Russia, and the Black SeaReason for Russia and Ukraine War 2022:Throughout 2021, bilateral tensions rose due to a Russian military buildup surrounding Ukrainian territoryLast updated question by NA on 07 May 2026', 0, 0, 0, 1790970548663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_37d6617069768746', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_defense', '''Hamas'' is the group of which country?', '{"A":"Egypt","B":"Iran","C":"Palestine","D":"Iraq"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hamas stands for the Islamic Resistance Movement and in Arabic means “zeal”.The group politically controls the Gaza Strip, a territory that is home to more than two million people but is blockaded by Israel.Hamas has been in power in the Gaza Strip since 2007 after a brief war against Fatah forces loyal to President Mahmoud Abbas, the head of the Palestinian Authority and Palestine Liberation Organization (PLO).', 0, 0, 0, 1790970548663) ON CONFLICT(id) DO NOTHING;
