INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_7a4f76be24d4b1c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_defense', 'In Sept 2023, Name the cyclone which hit the Libya, Greece, Turkiye, Bulgaria, Egypt and Israel?', '{"A":"Nargis","B":"Biparjoy","C":"Daniel","D":"Freddy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Details:Storm Daniel, also known as Cyclone Daniel, was the deadliest and costliest Mediterranean tropical-like cyclone ever recorded as well as the deadliest cyclone worldwide since Cyclone Nargis in 2008. It was also the deadliest weather event of 2023 to date. Libya was hit the hardest, with torrential rains causing two dams near the city of Derna to failFatalities 11,326Damage $2.16 billion', 0, 0, 0, 1790970548663) ON CONFLICT(id) DO NOTHING;
