INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_96c7e010da5acb98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_general', 'US forces withdrew from Afghanistan in?', '{"A":"September 2021","B":"August 2021","C":"July 2021","D":"December 2021"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The United States Armed Forces withdrew from Afghanistan on 31 August 2021.This withdrawal marked the end of the 2001–2021 War in Afghanistan.', 0, 0, 0, 1790970548740) ON CONFLICT(id) DO NOTHING;
