INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_ed79a6cbcaba74df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_general', 'Which is the highest railway bridge in the world?', '{"A":"Arrah–Chhapra Bridge","B":"Chenab Bridge","C":"Vijayghat Bridge","D":"Old Saraighat Bridge"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chenab Bridge is a rail bridge, located between Bakkal and Kauri in the Reasi district of Jammu and Kashmir (J&K), India. The 1,315m-long bridge is being built at a height of 359m.It is the tallest rail bridge in the world.', 0, 0, 0, 1790970548740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_333792cc7be803e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_general', 'Sanaa Marrin of Finland is famous ______?', '{"A":"Nuclear Scientist","B":"Youngest PM","C":"Astronaut","D":"Journalist","E":"Ukraine first lady"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sanna Marin became Finnish PM: December 2019Sanna Marin became the youngest person to became PM in Finland at the age of 34.Sanna Marin replaced Antti Rinne', 0, 0, 0, 1790970548749) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_783615f303c76c8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_general', 'Indian Citizenship Bill was recently passed on _____ ?', '{"A":"December 10, 2019","B":"December 11, 2019","C":"December 12, 2019","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Citizenship (Amendment) Act, 2019 was passed by the Parliament of India on 11 December 2019. It amended the Citizenship Act, 1955 by providing a path to Indian citizenship for illegal migrants of Muslims, Sikh, Buddhist, christian religious minorities', 0, 0, 0, 1790970548749) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tia_386736749b1d06d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_ia_general', 'In 2019-20 Australian Bush Fire Season is names as _____?', '{"A":"Dark summer","B":"White summer","C":"Black summer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 2019–20 Australian bushfire season is named as Black SummerThe fires reached their peak during the summer months, from December 2019 to February 2020.The extent of Damage: By early 2020, the bushfires had ravaged vast areas of Australia, burning an estimated 18 million hectares (44.5 million acres), destroying over 3,000 homes, and killing at least 33 people.', 0, 0, 0, 1790970548749) ON CONFLICT(id) DO NOTHING;
